<?php
require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json; charset=utf-8');
try{
 $where=[];$args=[];$q=trim($_GET['q']??'');if($q!==''){$where[]='(p.name LIKE ? OR p.brand LIKE ? OR c.category_name LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");}
 foreach(['brand'=>['Samsung','Apple'],'condition'=>['New','Used']] as $f=>$allowed)if(in_array($_GET[$f]??'',$allowed,true)){$where[]="p.`$f`=?";$args[]=$_GET[$f];}
 $cat=filter_var($_GET['category']??null,FILTER_VALIDATE_INT);if($cat){$where[]='p.category_id=?';$args[]=$cat;}$storage=trim($_GET['storage']??'');if($storage!==''){$where[]='p.storage=?';$args[]=$storage;}$quality=trim($_GET['quality']??'');if($quality!==''){$where[]='p.quality LIKE ?';$args[]='%'.$quality.'%';}if(($_GET['availability']??'')==='in')$where[]='p.stock>0';
 foreach(['min'=>'>=','max'=>'<='] as $f=>$op)if(isset($_GET[$f])&&$_GET[$f]!==''&&is_numeric($_GET[$f])&&(float)$_GET[$f]>=0){$where[]="p.price $op ?";$args[]=(float)$_GET[$f];}
 $sort=($_GET['sort']??'')==='low'?'p.price ASC':(($_GET['sort']??'')==='high'?'p.price DESC':'p.created_at DESC');$filter=' FROM products p LEFT JOIN categories c ON c.id=p.category_id'.($where?' WHERE '.implode(' AND ',$where):'');$count=db()->prepare('SELECT COUNT(*)'.$filter);$count->execute($args);$total=(int)$count->fetchColumn();$offset=max(0,min(100000,(int)($_GET['offset']??0)));
 $sql='SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image'.$filter." ORDER BY $sort LIMIT 48 OFFSET $offset";$s=db()->prepare($sql);$s->execute($args);$products=$s->fetchAll();ob_start();
 foreach($products as $p):$price=product_price((int)$p['id'],(float)$p['price']);?><article class="product-card"><a class="product-image" href="product-details.php?id=<?=$p['id']?>"><img loading="lazy" src="<?=image_url($p['image'])?>" alt="<?=e($p['brand'].' '.$p['name'])?>"></a><div class="product-info"><span class="badge <?=strtolower($p['brand'])?>"><?=e($p['brand'])?></span><button class="wishlist-toggle" type="button" data-product-id="<?=$p['id']?>" aria-label="Save <?=e($p['name'])?>">♡</button><h3><a href="product-details.php?id=<?=$p['id']?>"><?=e($p['name'])?></a></h3><p><?=e($p['storage'])?> · <?=e($p['condition'])?> · <?=e($p['quality'])?></p><strong><?=money($price)?></strong><?php if($price<(float)$p['price']):?><del><?=money($p['price'])?></del><?php endif?><span class="stock <?=$p['stock']>0?'in':'out'?>"><?=$p['stock']>0?$p['stock'].' in stock':'Out of stock'?></span><div class="card-actions"><a class="button dark-button" href="product-details.php?id=<?=$p['id']?>">View details</a><?php if($p['stock']>0):?><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="button primary" name="action" value="add">Add to cart</button></form><?php endif?></div></div></article><?php endforeach;
 $html=ob_get_clean();echo json_encode(['html'=>$html,'count'=>count($products),'total'=>$total,'hasMore'=>$total>$offset+count($products)]);
}catch(Throwable $e){http_response_code(500);echo json_encode(['error'=>'Could not load products']);}
